9	pub fn constant_evaluate<'a>(
10	    e: Node,
11	    expr_arena: &'a Arena<AExpr>,
12	    _schema: &Schema,
13	    _depth: usize,
14	) -> Option<Option<Cow<'a, LiteralValue>>> {
15	    match expr_arena.get(e) {
